import { HTMLAttributes } from 'react';
import { CommonProps } from '../../utility/commonProps';
/**
 * User information displayed in the avatar popover on hover/focus
 *
 * @example
 * ```tsx
 * const userInfo: AvatarInfo = {
 *   role: "Senior Frontend Developer",
 *   company: "Walmart Data Ventures",
 *   email: "john.doe@walmart.com"
 * };
 * ```
 */
export interface AvatarInfo {
    /**
     * User's job title or role
     * @example "Senior Frontend Developer", "Product Manager", "UX Designer"
     */
    role?: string;
    /**
     * User's company name
     * @example "Walmart Data Ventures", "Walmart Labs", "Sam's Club"
     */
    company?: string;
    /**
     * User's email address - displayed with email icon in popover
     * @example "john.doe@walmart.com"
     */
    email?: string;
}
/**
 * Avatar component props interface
 *
 * The Avatar component supports multiple content types, sizes, states, and interactive features.
 * It automatically handles fallbacks, accessibility, and provides rich hover information.
 *
 * @example Basic usage with initials
 * ```tsx
 * <Avatar
 *   type="initials"
 *   userName="John Doe"
 *   size="medium"
 * />
 * ```
 *
 * @example Image avatar with fallback
 * ```tsx
 * <Avatar
 *   type="image"
 *   src="/profile.jpg"
 *   userName="Jane Smith"
 *   size="large"
 * />
 * ```
 *
 * @example Interactive avatar with user info popover
 * ```tsx
 * <Avatar
 *   type="initials"
 *   userName="John Doe"
 *   focusable
 *   info={{
 *     role: "Senior Developer",
 *     company: "Walmart Data Ventures",
 *     email: "john.doe@walmart.com"
 *   }}
 *   onClick={handleUserClick}
 * />
 * ```
 *
 * @example Pending state for loading scenarios
 * ```tsx
 * <Avatar
 *   type="user-icon"
 *   state="pending"
 *   size="medium"
 * />
 * ```
 */
export interface AvatarProps extends CommonProps, Omit<HTMLAttributes<HTMLDivElement>, 'size'> {
    /**
     * Type of avatar content to display
     *
     * - `image`: Shows user profile picture from src URL with automatic fallback
     * - `initials`: Displays user initials extracted from userName
     * - `user-icon`: Shows generic user icon (default when no userName)
     * - `group-icon`: Shows group/team icon for collective avatars
     *
     * @default "initials"
     * @example
     * ```tsx
     * // Image with fallback to initials
     * <Avatar type="image" src="/profile.jpg" userName="John Doe" />
     *
     * // Initials only
     * <Avatar type="initials" userName="Jane Smith" />
     *
     * // Generic user icon
     * <Avatar type="user-icon" />
     *
     * // Group representation
     * <Avatar type="group-icon" />
     * ```
     */
    type?: 'image' | 'initials' | 'user-icon' | 'group-icon';
    /**
     * Avatar size variant
     *
     * Controls the diameter and font size of the avatar:
     * - `xsmall`: 24px - for compact lists or secondary UI
     * - `small`: 36px - for table rows or navigation
     * - `medium`: 48px - standard size for most use cases
     * - `large`: 80px - for profile headers or prominent display
     *
     * @default "medium"
     * @example
     * ```tsx
     * // Compact avatar for lists
     * <Avatar size="small" userName="John Doe" />
     *
     * // Standard avatar for cards
     * <Avatar size="medium" userName="Jane Smith" />
     *
     * // Prominent avatar for profiles
     * <Avatar size="large" userName="Bob Johnson" />
     * ```
     */
    size?: 'xsmall' | 'small' | 'medium' | 'large';
    /**
     * Avatar interactive and visual state
     *
     * - `enabled`: Normal interactive state (default)
     * - `disabled`: Non-interactive with muted appearance
     * - `pending`: Loading state with dashed border and muted colors
     *
     * @default "enabled"
     * @example
     * ```tsx
     * // Normal state
     * <Avatar userName="John Doe" state="enabled" />
     *
     * // Non-interactive
     * <Avatar userName="Jane Smith" state="disabled" />
     *
     * // Loading state
     * <Avatar type="user-icon" state="pending" />
     * ```
     */
    state?: 'enabled' | 'disabled' | 'pending';
    /**
     * Color scheme for initials and icon avatars
     *
     * - `auto`: Automatically assigns color based on userName hash (recommended)
     * - Named colors: Specific brand colors for manual assignment
     *
     * Note: Color only applies to initials and icon types, not images.
     * Disabled and pending states override color selections.
     *
     * @default "auto"
     * @example
     * ```tsx
     * // Automatic color assignment (recommended)
     * <Avatar userName="John Doe" color="auto" />
     *
     * // Manual color assignment
     * <Avatar userName="Jane Smith" color="blue" />
     *
     * // Icon with specific color
     * <Avatar type="user-icon" color="green" />
     * ```
     */
    color?: 'auto' | 'blue' | 'green' | 'yellow' | 'pink' | 'orange' | 'cyan' | 'purple' | 'red' | 'spark';
    /**
     * Source URL for image avatar
     *
     * When provided with type="image", displays the image from this URL.
     * Automatically falls back to initials or user-icon if image fails to load.
     * Should be optimized for the avatar size (square aspect ratio recommended).
     *
     * @example
     * ```tsx
     * // Image avatar with fallback
     * <Avatar
     *   type="image"
     *   src="https://example.com/profile.jpg"
     *   userName="John Doe"
     * />
     *
     * // Image will fallback to initials if URL fails
     * <Avatar
     *   type="image"
     *   src="/broken-link.jpg"
     *   userName="Jane Smith"
     * />
     * ```
     */
    src?: string;
    /**
     * User name for generating initials and accessibility labels
     *
     * Used to:
     * - Extract initials for display (first letter of first/last names)
     * - Generate accessible alt text and ARIA labels
     * - Create consistent auto color assignment
     * - Provide fallback when image loading fails
     *
     * @example
     * ```tsx
     * // Generates "JD" initials
     * <Avatar userName="John Doe" type="initials" />
     *
     * // Single name generates single initial
     * <Avatar userName="Madonna" type="initials" />
     *
     * // Multi-word names use first and last
     * <Avatar userName="Mary Jane Watson" type="initials" /> // "MW"
     * ```
     */
    userName?: string;
    /**
     * Whether the avatar should be keyboard focusable and interactive
     *
     * When true:
     * - Avatar becomes focusable via Tab key
     * - Receives role="button" for screen readers
     * - Supports Enter/Space key activation
     * - Shows focus outline on keyboard navigation
     * - Required for clickable avatars
     *
     * @default false
     * @example
     * ```tsx
     * // Interactive avatar for user profiles
     * <Avatar
     *   userName="John Doe"
     *   focusable
     *   onClick={openUserProfile}
     * />
     *
     * // Non-interactive display avatar
     * <Avatar userName="Jane Smith" focusable={false} />
     * ```
     */
    focusable?: boolean;
    /**
     * User information displayed in popover on hover/focus
     *
     * When provided, shows a rich popover with user details on mouse hover
     * or keyboard focus. Popover includes avatar, name, role, company, and email.
     * Automatically manages popover positioning and accessibility.
     *
     * @example
     * ```tsx
     * // Full user info popover
     * <Avatar
     *   userName="John Doe"
     *   info={{
     *     role: "Senior Frontend Developer",
     *     company: "Walmart Data Ventures",
     *     email: "john.doe@walmart.com"
     *   }}
     * />
     *
     * // Minimal info popover
     * <Avatar
     *   userName="Jane Smith"
     *   info={{ role: "Product Manager" }}
     * />
     * ```
     */
    info?: AvatarInfo;
    /**
     * Additional CSS classes to apply to the avatar
     * @example
     * ```tsx
     * <Avatar userName="John Doe" className="custom-avatar-style" />
     * ```
     */
    className?: string;
    /**
     * Test identifier for automated testing
     * @example
     * ```tsx
     * <Avatar userName="John Doe" data-testid="user-avatar" />
     * ```
     */
    'data-testid'?: string;
}
/**
 * Avatar content type union
 * @see {@link AvatarProps.type} for detailed usage examples
 */
export type AvatarType = AvatarProps['type'];
/**
 * Avatar size variant union
 * @see {@link AvatarProps.size} for detailed usage examples
 */
export type AvatarSize = AvatarProps['size'];
/**
 * Avatar state union for interactive and visual states
 * @see {@link AvatarProps.state} for detailed usage examples
 */
export type AvatarState = AvatarProps['state'];
/**
 * Avatar color scheme union for initials and icon avatars
 * @see {@link AvatarProps.color} for detailed usage examples
 */
export type AvatarColor = AvatarProps['color'];
